import { TypeSafeClient, Choice, Noul } from '@typesafe-ai/sdk';

const client = new TypeSafeClient();
const decision = await client.evaluate({
  state: { query: "Urgent: refund my order!" },
  questions: {
    intent: Choice(["refund", "support", "faq"]),
    is_urgent: Noul() // Returns probability
  }
});

if (decision.intent === "refund" && decision.is_urgent > 0.8) {
  await triggerAutoEscalation();
}
